  about_title: 'About grandma.app',
  about_tagline: 'your knowing companion',
  about_missionTitle: 'Our mission',
  about_missionBody: 'To be the calm, knowing presence beside every parent — from trying, through pregnancy, into the early years. Support that feels like family.',
  about_expertiseTitle: 'Grounded in expertise',
  about_expertiseBody: "Grandma’s guidance is built on OB-GYN, midwife, and pediatric knowledge. It’s caring support — never a substitute for your own doctor.",
