  // ─── Phase 1: Help & FAQ hub ──────────────────────────────────────────────
  help_title: 'Help & FAQ',
  help_subtitle: 'we’re here for you',
  help_searchPlaceholder: 'What would you like to find?',
  help_noResults: 'No answers matched. Try different words, or contact us below.',
  help_stillStuck: 'Still need a hand?',
  help_stillStuckBody: 'Can’t find your answer? Our team is happy to help.',
  help_contactUs: 'Contact us',
  help_catStart: 'Getting Started',
  help_catAccount: 'Account & Data',
  help_catCare: 'Care Circle',
  help_catAi: "Grandma AI",
  help_catBilling: 'Subscriptions & Billing',
  help_catPrivacy: 'Privacy',
  help_q_modes: 'What are journey modes?',
  help_a_modes: "grandma.app adapts to where you are: Cycle (following your cycle or trying to conceive), Pregnancy, Kids (parenting 0–5) and Menopause. Each journey changes your home, what you log and Grandma's guidance.",
  help_q_switchMode: 'How do I switch modes?',
  help_a_switchMode: "Open the Settings tab and tap a journey under My Journey. Each journey keeps its own data, so nothing is lost when you switch.",
  help_q_logging: 'How do I log something?',
  help_a_logging: "Log from your home screen or the Calendar tab — pick the day and what to note: period, symptoms, mood, sleep and more. Everything shows up on your calendar and in your Notes.",
  help_q_export: 'How do I export my data?',
  help_a_export: 'Go to Settings → Data & Privacy → Data We Hold → Export all my data. You’ll get a complete machine-readable JSON copy of everything we store.',
  help_q_delete: 'How do I delete my account?',
  help_a_delete: 'Settings → Account → Delete account. This permanently erases your data from our systems and cannot be undone.',
  help_q_password: 'How do I change my password?',
  help_a_password: 'Settings → Account → Change password. If you signed in with Apple or Google, manage your login through that provider.',
  help_q_invite: 'How do I invite my care circle?',
  help_a_invite: 'Settings → Care Circle → Invite. Send a secure link to a partner, nanny, or grandparent. They join with the exact permissions you choose.',
  help_q_permissions: 'Can I control what caregivers see?',
  help_a_permissions: 'Yes. Each caregiver has permissions you set — you decide who can view or add logs, health records, and more. Change or revoke access anytime.',
  help_q_grandma: "Who is Grandma?",
  help_a_grandma: "Grandma is your AI companion, powered by Claude. She answers questions with context from your journey and offers warm, practical guidance day or night.",
  help_q_medical: "Is Grandma’s advice medical advice?",
  help_a_medical: "No. Grandma offers caring, educational guidance — not diagnosis or treatment. Always consult your doctor, midwife, or pediatrician for medical concerns.",
  help_q_premium: 'What does Premium include?',
  help_a_premium: 'Premium unlocks unlimited scans and chat, full insights, and reminders. You can subscribe monthly or annually.',
  help_q_cancel: 'How do I cancel Premium?',
  help_a_cancel: 'Manage or cancel your subscription anytime in your app-store account settings. Your Premium features stay active until the end of the billing period.',
  help_q_dataSafe: 'Is my data safe?',
  help_a_dataSafe: 'Yes. Your data is encrypted in transit and at rest, protected by row-level security so only you and the care circle you choose can access it.',
  help_q_sell: 'Do you sell my data?',
  help_a_sell: 'Never. We do not sell your personal data, and we never use your private health or child data to train third-party AI.',

