  // ─── Phase 1 / WS3: Community Guidelines screen ───────────────────────────
  guidelines_title: 'Community Guidelines',
  guidelines_subtitle: 'a kind place to share',
  guidelines_intro: 'grandma.app is a space for parents to support each other honestly. To keep it safe for everyone, we ask you to follow a few simple rules.',
  guidelines_rule1Title: 'Be kind and respectful',
  guidelines_rule1Body: 'Everyone here is on their own journey. No harassment, bullying, hate speech, or personal attacks.',
  guidelines_rule2Title: 'Protect privacy',
  guidelines_rule2Body: 'Don’t share others’ personal or health information. Be thoughtful about what you reveal about your own family, too.',
  guidelines_rule3Title: 'Share support, not diagnosis',
  guidelines_rule3Body: 'Offer experience and encouragement — not medical directions. For medical concerns, always point people to their doctor.',
  guidelines_rule4Title: 'No spam or selling',
  guidelines_rule4Body: 'Keep the community about connection, not promotion. Marketplace listings belong in the exchange, not the feed.',
  guidelines_rule5Title: 'Keep it safe',
  guidelines_rule5Body: 'No content that promotes self-harm, danger to children, or anything illegal. We remove it and may suspend the account.',
  guidelines_sectionReport: 'If You See Something',
  guidelines_reportBody: 'Long-press any post or message to report it or block the person. Reports are private and reviewed by our team. In an emergency, always contact local emergency services.',
  guidelines_footer: 'Breaking these rules may lead to content removal or account suspension. Thank you for keeping this community safe.',

