  sw2_leap19_name: "Events",
  sw2_leap19_desc: "Understanding that actions happen in sequences",
  sw2_leap19_brain: "Around now, babies often start to notice the world as a series of events rather than one big blur. Actions have a beginning, a middle and an end. This is the start of cause-and-effect thinking, and why everything can suddenly seem so fascinating.",
  sw2_leap19_tip: "Play simple cause-and-effect games like peek-a-boo — baby is learning that events have predictable outcomes.",
  sw2_leap19_ph0: "Clingy, cries when put down, sleep disrupted. Baby may feel worn out as so much new happens all at once.",
  sw2_leap19_ph1: "Baby is often busy linking actions to what happens next — pushing, dropping, watching closely.",
  sw2_leap19_ph2: "Intentional reaching appears, along with early object permanence — baby looks for dropped items.",
  sw2_leap19_sg0: "Separation anxiety spike",
  sw2_leap19_sg1: "Very clingy",
  sw2_leap19_sg2: "Crying when toy falls",
  sw2_leap19_sg3: "Resists naps",
  sw2_leap19_sg4: "Demands interaction",
  sw2_leap19_sg5: "Frustrated when routine breaks",
  sw2_leap19_sk0: "Reaches & grabs intentionally",
  sw2_leap19_sk1: "Shakes & bangs toys",
  sw2_leap19_sk2: "Recognizes games",
  sw2_leap19_sk3: "Understands \"up\" & \"down\"",
  sw2_leap19_sk4: "Follows moving objects with eyes",
  sw2_leap19_sk5: "Laughs at surprises",
  sw2_leap19_ac0: "Peek-a-boo and hide-and-seek games",
  sw2_leap19_ac1: "Rolling a ball back and forth",
  sw2_leap19_ac2: "Simple cause-effect toys (press = sound)",
  sw2_leap19_ac3: "Narrate daily routines step-by-step",
  sw2_leap5_name: "Changing Sensations",
  sw2_leap5_desc: "Baby discovers a richer world of senses",
  sw2_leap5_brain: "Around now, your baby may start taking in much more detail from the senses — sharper sights, richer sounds, new body feelings. It can feel big, and wonderful, at the same time.",
  sw2_leap5_ph0: "More crying, clinginess and unsettled sleep are common. Baby may be taking in a lot of new sensory information.",
  sw2_leap5_ph1: "Baby is taking in lots of new sights and sounds. Fussiness may peak before calming.",
  sw2_leap5_ph2: "New sensory awareness blossoms — you'll notice longer alert periods and more deliberate looking.",
  sw2_leap5_sg0: "More crying than usual",
  sw2_leap5_sg1: "Wants to feed constantly",
  sw2_leap5_sg2: "Harder to settle",
  sw2_leap5_sg3: "Prefers closeness",
  sw2_leap5_sg4: "Startles more easily",
  sw2_leap5_sg5: "Dislikes being undressed",
  sw2_leap5_sk0: "Reacts to light & sound",
  sw2_leap5_sk1: "Smoother gaze tracking",
  sw2_leap5_sk2: "Early social smile",
  sw2_leap5_sk3: "More alert periods",
  sw2_leap5_sk4: "Turns toward your voice",
  sw2_leap5_sk5: "Notices high-contrast patterns",
  sw2_leap5_ac0: "Hold baby facing outward to explore the room",
  sw2_leap5_ac1: "Show high-contrast black & white cards",
  sw2_leap5_ac2: "Narrate everything you do out loud",
  sw2_leap5_ac3: "Gentle baby massage during calm moments",
  sw2_leap5_tip: "Skin-to-skin contact is powerful right now. Babywearing and gentle rocking can ease fussy days.",
